INSERT INTO public.exercise_library (id, name, slug, body_area, movement_type, equipment, level, primary_muscles, secondary_muscles, instructions, image_paths, legacy_names) VALUES
  ('Split_Squats', 'Split Squats', 'split-squats', 'Mobility & Stretching', 'Squat', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['hamstrings']::text[], ARRAY['calves', 'glutes', 'quadriceps']::text[], ARRAY['Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.', 'As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.']::text[], ARRAY['/exercises/split-squats-1.webp', '/exercises/split-squats-2.webp']::text[], ARRAY['Split squat']::text[]),
  ('Standing_Dumbbell_Calf_Raise', 'Standing Dumbbell Calf Raise', 'standing-dumbbell-calf-raise', 'Legs & Glutes', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.', 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.', 'As you inhale, go back to the starting position by slowly lowering the heels.', 'Repeat for the recommended amount of times.']::text[], ARRAY['/exercises/standing-dumbbell-calf-raise-1.webp', '/exercises/standing-dumbbell-calf-raise-2.webp']::text[], ARRAY['Dumbbell calf raise']::text[]),
  ('Standing_Dumbbell_Triceps_Extension', 'Standing Dumbbell Triceps Extension', 'standing-dumbbell-triceps-extension', 'Arms', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['triceps']::text[], ARRAY[]::text[], ARRAY['To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.', 'The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.', 'Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/standing-dumbbell-triceps-extension-1.webp', '/exercises/standing-dumbbell-triceps-extension-2.webp']::text[], ARRAY['Overhead triceps extension']::text[]),
  ('Tricep_Dumbbell_Kickback', 'Tricep Dumbbell Kickback', 'tricep-dumbbell-kickback', 'Arms', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['triceps']::text[], ARRAY[]::text[], ARRAY['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/tricep-dumbbell-kickback-1.webp', '/exercises/tricep-dumbbell-kickback-2.webp']::text[], ARRAY['Triceps kickback']::text[]),
  ('3_4_Sit-Up', '3/4 Sit-Up', '3-4-sit-up', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Lie down on the floor and secure your feet. Your legs should be bent at the knees.', 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.', 'Flex your hips and spine to raise your torso toward your knees.', 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/3-4-sit-up-1.webp', '/exercises/3-4-sit-up-2.webp']::text[], ARRAY[]::text[]),
  ('90_90_Hamstring', '90/90 Hamstring', '90-90-hamstring', 'Mobility & Stretching', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['hamstrings']::text[], ARRAY['calves']::text[], ARRAY['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.']::text[], ARRAY['/exercises/90-90-hamstring-1.webp', '/exercises/90-90-hamstring-2.webp']::text[], ARRAY[]::text[]),
  ('Ab_Crunch_Machine', 'Ab Crunch Machine', 'ab-crunch-machine', 'Core', 'Core', ARRAY['Machine']::text[], 'Intermediate', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['/exercises/ab-crunch-machine-1.webp', '/exercises/ab-crunch-machine-2.webp']::text[], ARRAY[]::text[]),
  ('Advanced_Kettlebell_Windmill', 'Advanced Kettlebell Windmill', 'advanced-kettlebell-windmill', 'Core', 'Core', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['abdominals']::text[], ARRAY['glutes', 'hamstrings', 'shoulders']::text[], ARRAY['Clean and press a kettlebell overhead with one arm.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.', 'Lower yourself as far as possible.', 'Pause for a second and reverse the motion back to the starting position.']::text[], ARRAY['/exercises/advanced-kettlebell-windmill-1.webp', '/exercises/advanced-kettlebell-windmill-2.webp']::text[], ARRAY[]::text[]),
  ('All_Fours_Quad_Stretch', 'All Fours Quad Stretch', 'all-fours-quad-stretch', 'Mobility & Stretching', 'Push', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['quadriceps']::text[], ARRAY['quadriceps']::text[], ARRAY['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.', 'Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.', 'Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.']::text[], ARRAY['/exercises/all-fours-quad-stretch-1.webp', '/exercises/all-fours-quad-stretch-2.webp']::text[], ARRAY[]::text[]),
  ('Alternate_Hammer_Curl', 'Alternate Hammer Curl', 'alternate-hammer-curl', 'Arms', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[], ARRAY['/exercises/alternate-hammer-curl-1.webp', '/exercises/alternate-hammer-curl-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Cable_Shoulder_Press', 'Alternating Cable Shoulder Press', 'alternating-cable-shoulder-press', 'Shoulders', 'Push', ARRAY['Machine']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['Move the cables to the bottom of the tower and select an appropriate weight.', 'Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press one side directly over head.', 'After pausing at the top, return to the starting position and repeat on the opposite side.']::text[], ARRAY['/exercises/alternating-cable-shoulder-press-1.webp', '/exercises/alternating-cable-shoulder-press-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Deltoid_Raise', 'Alternating Deltoid Raise', 'alternating-deltoid-raise', 'Shoulders', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY[]::text[], ARRAY['In a standing position, hold a pair of dumbbells at your side.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'Return the weights to your side.', 'On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.', 'Return the weights to the starting position and continue alternating to the front and side.']::text[], ARRAY['/exercises/alternating-deltoid-raise-1.webp', '/exercises/alternating-deltoid-raise-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Floor_Press', 'Alternating Floor Press', 'alternating-floor-press', 'Chest', 'Push', ARRAY['Kettlebell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['abdominals', 'shoulders', 'triceps']::text[], ARRAY['Lie on the floor with two kettlebells next to your shoulders.', 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.', 'Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.', 'Raise the kettlebell and repeat on the opposite side.']::text[], ARRAY['/exercises/alternating-floor-press-1.webp', '/exercises/alternating-floor-press-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Hang_Clean', 'Alternating Hang Clean', 'alternating-hang-clean', 'Legs & Glutes', 'Pull', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['hamstrings']::text[], ARRAY['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'traps']::text[], ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.', 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[], ARRAY['/exercises/alternating-hang-clean-1.webp', '/exercises/alternating-hang-clean-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Kettlebell_Press', 'Alternating Kettlebell Press', 'alternating-kettlebell-press', 'Shoulders', 'Push', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .', 'Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[], ARRAY['/exercises/alternating-kettlebell-press-1.webp', '/exercises/alternating-kettlebell-press-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Kettlebell_Row', 'Alternating Kettlebell Row', 'alternating-kettlebell-row', 'Back', 'Pull', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['middle back']::text[], ARRAY['biceps', 'lats']::text[], ARRAY['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', 'Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.', 'Lower the kettlebell in the working arm and repeat with your other arm.']::text[], ARRAY['/exercises/alternating-kettlebell-row-1.webp', '/exercises/alternating-kettlebell-row-2.webp']::text[], ARRAY[]::text[]),
  ('Alternating_Renegade_Row', 'Alternating Renegade Row', 'alternating-renegade-row', 'Back', 'Pull', ARRAY['Kettlebell']::text[], 'Expert', ARRAY['middle back']::text[], ARRAY['abdominals', 'biceps', 'chest', 'lats', 'triceps']::text[], ARRAY['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', 'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.', 'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[], ARRAY['/exercises/alternating-renegade-row-1.webp', '/exercises/alternating-renegade-row-2.webp']::text[], ARRAY[]::text[]),
  ('Anti-Gravity_Press', 'Anti-Gravity Press', 'anti-gravity-press', 'Shoulders', 'Push', ARRAY['Barbell']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['middle back', 'traps', 'triceps']::text[], ARRAY['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.', 'To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.', 'Return to the starting position and repeat to complete the set.']::text[], ARRAY['/exercises/anti-gravity-press-1.webp', '/exercises/anti-gravity-press-2.webp']::text[], ARRAY[]::text[]),
  ('Arnold_Dumbbell_Press', 'Arnold Dumbbell Press', 'arnold-dumbbell-press', 'Shoulders', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.', 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.', 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/arnold-dumbbell-press-1.webp', '/exercises/arnold-dumbbell-press-2.webp']::text[], ARRAY[]::text[]),
  ('Around_The_Worlds', 'Around The Worlds', 'around-the-worlds', 'Chest', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['chest']::text[], ARRAY['shoulders']::text[], ARRAY['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.', 'Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.', 'Reverse the movement to return the weight to the starting position as you exhale.']::text[], ARRAY['/exercises/around-the-worlds-1.webp', '/exercises/around-the-worlds-2.webp']::text[], ARRAY[]::text[]),
  ('Back_Flyes_-_With_Bands', 'Back Flyes - With Bands', 'back-flyes-with-bands', 'Shoulders', 'Pull', ARRAY['Band']::text[], 'Beginner', ARRAY['shoulders']::text[], ARRAY['middle back', 'triceps']::text[], ARRAY['Run a band around a stationary post like that of a squat rack.', 'Grab the band by the handles and stand back so that the tension in the band rises.', 'Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.', 'As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.', 'After a pause, go back to the original position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/back-flyes-with-bands-1.webp', '/exercises/back-flyes-with-bands-2.webp']::text[], ARRAY[]::text[]),
  ('Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'band-assisted-pull-up', 'Back', 'Pull', ARRAY['Bar']::text[], 'Beginner', ARRAY['lats']::text[], ARRAY['abdominals', 'forearms', 'middle back']::text[], ARRAY['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.']::text[], ARRAY['/exercises/band-assisted-pull-up-1.webp', '/exercises/band-assisted-pull-up-2.webp']::text[], ARRAY[]::text[]),
  ('Band_Good_Morning', 'Band Good Morning', 'band-good-morning', 'Legs & Glutes', 'Hinge', ARRAY['Band']::text[], 'Beginner', ARRAY['hamstrings']::text[], ARRAY['glutes', 'lower back']::text[], ARRAY['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', 'Keeping your legs straight, extend through the hips to come to a near vertical position.', 'Ensure that you do not round your back as you go down back to the starting position.']::text[], ARRAY['/exercises/band-good-morning-1.webp', '/exercises/band-good-morning-2.webp']::text[], ARRAY[]::text[]),
  ('Band_Skull_Crusher', 'Band Skull Crusher', 'band-skull-crusher', 'Arms', 'Push', ARRAY['Band']::text[], 'Beginner', ARRAY['triceps']::text[], ARRAY[]::text[], ARRAY['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.', 'Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.', 'Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[], ARRAY['/exercises/band-skull-crusher-1.webp', '/exercises/band-skull-crusher-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Ab_Rollout', 'Barbell Ab Rollout', 'barbell-ab-rollout', 'Core', 'Core', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['abdominals']::text[], ARRAY['lower back', 'shoulders']::text[], ARRAY['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.', 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-ab-rollout-1.webp', '/exercises/barbell-ab-rollout-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Ab_Rollout_-_On_Knees', 'Barbell Ab Rollout - On Knees', 'barbell-ab-rollout-on-knees', 'Core', 'Core', ARRAY['Barbell']::text[], 'Expert', ARRAY['abdominals']::text[], ARRAY['lower back', 'shoulders']::text[], ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], ARRAY['/exercises/barbell-ab-rollout-on-knees-1.webp', '/exercises/barbell-ab-rollout-on-knees-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'barbell-bench-press-medium-grip', 'Chest', 'Push', ARRAY['Barbell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['/exercises/barbell-bench-press-medium-grip-1.webp', '/exercises/barbell-bench-press-medium-grip-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Curl', 'Barbell Curl', 'barbell-curl', 'Arms', 'Pull', ARRAY['Barbell']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-curl-1.webp', '/exercises/barbell-curl-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Deadlift', 'Barbell Deadlift', 'barbell-deadlift', 'Back', 'Hinge', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['lower back']::text[], ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lats', 'middle back', 'quadriceps', 'traps']::text[], ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], ARRAY['/exercises/barbell-deadlift-1.webp', '/exercises/barbell-deadlift-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Full_Squat', 'Barbell Full Squat', 'barbell-full-squat', 'Legs & Glutes', 'Squat', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings', 'lower back']::text[], ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-full-squat-1.webp', '/exercises/barbell-full-squat-2.webp']::text[], ARRAY[]::text[])
